#!/bin/sh
# VPN Selector for OpenWrt: installs LuCI -> Services -> VPN Regions and the
# region-aware WireGuard failover (/usr/bin/vpn-failover.sh), with automatic
# hotel Wi-Fi login and no DNS leaks.
#
# Copy to the router and run it:
#   scp -O install.sh root@192.168.1.1:/tmp/
#   ssh root@192.168.1.1 sh /tmp/install.sh [--killswitch]
#
#   --killswitch   remove LAN -> WAN forwarding, so LAN traffic can only leave
#                  through a VPN tunnel (nothing goes out while no tunnel is up)
#
# Safe to run again to update; your tunnels and settings are kept.
# This file is generated by tools/build-installer.sh from files/; edit those.
set -e

KILLSWITCH=0
for a in "$@"; do
  case "$a" in
    --killswitch) KILLSWITCH=1 ;;
    -h|--help) sed -n '2,13p' "$0"; exit 0 ;;
    *) echo "unknown option: $a" >&2; exit 1 ;;
  esac
done

# --- packages -------------------------------------------------------------
need=""
command -v curl >/dev/null || need="$need curl"
command -v wg >/dev/null || need="$need wireguard-tools"
[ -d /sys/module/wireguard ] || modinfo wireguard >/dev/null 2>&1 || need="$need kmod-wireguard"
[ -f /lib/netifd/proto/wireguard.sh ] || need="$need wireguard-tools"
[ -f /www/luci-static/resources/protocol/wireguard.js ] || need="$need luci-proto-wireguard"
command -v jsonfilter >/dev/null || need="$need jsonfilter"
if [ -n "$need" ]; then
  echo "Installing:$need"
  if command -v apk >/dev/null; then apk update && apk add $need
  else opkg update && opkg install $need; fi
fi

[ -f /usr/bin/vpn-failover.sh ] && [ ! -f /usr/bin/vpn-failover.sh.orig ] && \
  cp /usr/bin/vpn-failover.sh /usr/bin/vpn-failover.sh.orig

# --- settings -------------------------------------------------------------
# Seed the tunnel list from any existing WireGuard interfaces, with the region
# taken from the name (VPN_Canada -> Canada). The uplink is travelmate's wwan
# if there is one, otherwise wan.
if [ ! -s /etc/config/vpnregions ]; then
  old=$(sed -n 's/^VPNS="\([^"]*\)".*/\1/p' /usr/bin/vpn-failover.sh 2>/dev/null)
  wg=$(uci show network | sed -n "s/^network\.\([^.]*\)\.proto='wireguard'$/\1/p")
  uplink=wan; [ -n "$(uci -q get network.wwan)" ] && uplink=wwan
  touch /etc/config/vpnregions
  uci set vpnregions.main=settings
  uci set vpnregions.main.enabled='1'
  uci set vpnregions.main.region='all'
  uci set vpnregions.main.uplink="$uplink"
  uci set vpnregions.main.grace='60'
  uci set vpnregions.main.maxage='180'
  seen=" "
  for i in $old $wg; do
    case "$seen" in *" $i "*) continue;; esac
    seen="$seen$i "
    [ "$(uci -q get network.$i.proto)" = wireguard ] || continue
    s=$(uci add vpnregions tunnel)
    uci set vpnregions.$s.iface="$i"
    uci set vpnregions.$s.region="$(echo "${i#VPN_}" | tr -c 'A-Za-z0-9_\n-' _)"
    uci set vpnregions.$s.enabled='1'
  done
  uci commit vpnregions
fi

# --- firewall -------------------------------------------------------------
# Tunnels go in a zone called VPN (masquerade, MSS clamping) that the LAN may
# forward to. Imported configs are added to it from the LuCI page.
fw_changed=0
zone=""
for z in $(uci show firewall | sed -n "s/^firewall\.\([^.]*\)=zone$/\1/p"); do
  [ "$(uci -q get firewall.$z.name)" = VPN ] && zone=$z
done
if [ -z "$zone" ]; then
  zone=$(uci add firewall zone)
  uci set firewall.$zone.name='VPN'
  uci set firewall.$zone.input='REJECT'
  uci set firewall.$zone.output='ACCEPT'
  uci set firewall.$zone.forward='REJECT'
  uci set firewall.$zone.masq='1'
  uci set firewall.$zone.mtu_fix='1'
  # existing tunnels that are in no zone yet
  for i in $(uci show vpnregions | sed -n "s/^vpnregions\.[^.]*\.iface='\(.*\)'$/\1/p"); do
    uci show firewall | grep -q "\.network=.*'$i'" || uci add_list firewall.$zone.network="$i"
  done
  fw_changed=1
  echo "Created firewall zone VPN."
fi
has_fwd() {
  for f in $(uci show firewall | sed -n "s/^firewall\.\([^.]*\)=forwarding$/\1/p"); do
    [ "$(uci -q get firewall.$f.src)" = "$1" ] && [ "$(uci -q get firewall.$f.dest)" = "$2" ] && echo "$f"
  done
}
if [ -z "$(has_fwd lan VPN)" ]; then
  f=$(uci add firewall forwarding)
  uci set firewall.$f.src='lan'
  uci set firewall.$f.dest='VPN'
  fw_changed=1
fi
if [ "$KILLSWITCH" = 1 ]; then
  for f in $(has_fwd lan wan); do uci delete firewall.$f; fw_changed=1; echo "Kill switch on: removed LAN -> WAN forwarding."; done
fi
if [ "$fw_changed" = 1 ]; then
  uci commit firewall
  /etc/init.d/firewall reload >/dev/null 2>&1 || true
fi

mkdir -p /www/luci-static/resources/view /usr/share/luci/menu.d /usr/share/rpcd/acl.d

cat > /usr/bin/vpn-failover.sh <<'VPNREGIONS_EOF'
#!/bin/sh
# vpn-failover: keep exactly one WireGuard tunnel up and move to the next
# one in the list when it stops working. Run from cron once a minute.
#
# The tunnels, their regions and the active region live in
# /etc/config/vpnregions and are edited in LuCI under Services -> VPN Regions.
#
#   vpn-failover.sh               normal check (what cron runs)
#   vpn-failover.sh next          switch to the next tunnel in the region now
#   vpn-failover.sh portal [min]  hotel login: let the LAN out over the plain
#                                 uplink for a few minutes, VPN kept down
#   vpn-failover.sh portal close  end the hotel login window early
#
# Travelmate looks after the Wi-Fi uplink; this script owns the VPN. Keep
# travelmate's own VPN option off (trm_vpn=0) or the two fight.

export PATH=/usr/sbin:/usr/bin:/sbin:/bin
. /lib/functions.sh

STATE="/tmp/vpn-failover"
LOCK="/tmp/vpn-failover.lock"
PORTAL="/tmp/vpn-portal"   # holds the time the hotel login window closes
TRM_RT="/var/run/travelmate/travelmate.runtime.json"
DNSFILE="/tmp/resolv.conf.vpnregions"            # dnsmasq's resolvfile
DNSAUTO="/tmp/resolv.conf.d/resolv.conf.auto"    # every interface's DNS

log() { logger -t vpn-failover "$*"; }

# Only one copy at a time (cron and the LuCI buttons can overlap), so wait
# for a running copy to finish. A lock left behind by a killed run is
# cleared after 5 minutes.
n=0
until mkdir "$LOCK" 2>/dev/null; do
  if [ $(($(date +%s) - $(date -r "$LOCK" +%s 2>/dev/null || date +%s))) -gt 300 ]; then
    rm -rf "$LOCK"
  else
    n=$((n + 1)); [ "$n" -gt 30 ] && exit 0; sleep 1
  fi
done
trap 'rmdir "$LOCK" 2>/dev/null' EXIT

config_load vpnregions
config_get_bool ENABLED main enabled 1
config_get REGION main region all
config_get UPLINK main uplink wwan
config_get GRACE main grace 60     # seconds a freshly started tunnel gets to handshake
config_get MAXAGE main maxage 180  # a handshake older than this counts as dead
config_get PORTALMIN main portal_minutes 5
config_get_bool PORTALAUTO main portal_auto 1

ALL=""   # every tunnel this script manages
VPNS=""  # the enabled tunnels in the chosen region, in order of preference
add_tunnel() {
  local iface region enabled
  config_get iface "$1" iface
  config_get region "$1" region
  config_get_bool enabled "$1" enabled 1
  [ -n "$iface" ] || return 0
  ALL="$ALL $iface"
  [ "$enabled" = 1 ] || return 0
  [ "$REGION" = all ] || [ "$region" = "$REGION" ] || return 0
  VPNS="$VPNS $iface"
}
config_foreach add_tunnel tunnel

is_up() { [ "$(ifstatus "$1" 2>/dev/null | jsonfilter -e '@.up')" = "true" ]; }
in_list() { case " $2 " in *" $1 "*) return 0;; esac; return 1; }
# DNS: while a tunnel is up dnsmasq only asks that tunnel's DNS servers, so
# the hotel never sees which names are looked up. With no tunnel (starting
# up, or a hotel login) it uses the uplink's DNS so portals and the
# router's own checks still resolve.
set_dns() {
  local want=""
  [ -n "$1" ] && want="$(ifstatus "$1" 2>/dev/null | jsonfilter -e '@["dns-server"][*]' | sed 's/^/nameserver /')"
  [ -n "$want" ] || want="$(grep -v '^#' "$DNSAUTO" 2>/dev/null)"
  [ "$want" = "$(cat "$DNSFILE" 2>/dev/null)" ] || echo "$want" > "$DNSFILE"
}
all_down() {
  for v in $ALL; do is_up "$v" && ifdown "$v"; done
  rm -f "$STATE"
  set_dns
}

# Hotel login window: one runtime firewall rule lets the LAN forward to the
# uplink, which the kill switch otherwise forbids. It is not saved anywhere,
# so a firewall reload or reboot drops it; the window re-adds it while open.
portal_rules() {
  nft -a list chain inet fw4 forward_lan 2>/dev/null |
    sed -n 's/.*comment "vpn-portal".*# handle \([0-9]*\)$/\1/p'
}
portal_open_rule() {
  [ -n "$1" ] && [ -z "$(portal_rules)" ] || return 0
  nft insert rule inet fw4 forward_lan oifname "\"$1\"" counter accept comment '"vpn-portal"'
}
portal_close() {
  for h in $(portal_rules); do nft delete rule inet fw4 forward_lan handle "$h"; done
  [ -f "$PORTAL" ] && log "hotel login window closed"
  rm -f "$PORTAL"
}

# Travelmate's last check of the uplink found a captive portal, and a fresh
# check agrees (its status can lag behind a login that just went through).
trm_portal() {
  [ "$(uci -q get travelmate.global.trm_enabled)" = 1 ] || return 1
  case "$(jsonfilter -i "$TRM_RT" -e '@.data.travelmate_status' 2>/dev/null)" in
    *"net cp"*) ;;
    *) return 1 ;;
  esac
  [ "$(curl -s -m 8 --interface "$dev" http://detectportal.firefox.com/success.txt 2>/dev/null | tr -d ' \r\n')" != success ]
}

# Try the automatic hotel login, at most every 5 minutes per access point.
portal_autologin() {
  [ "$PORTALAUTO" = 1 ] && [ -x /usr/bin/vpn-portal-login ] || return 1
  local ap last t
  ap="$(iwinfo "$dev" info 2>/dev/null | sed -n 's/.*Access Point: \([0-9A-Fa-f:]*\).*/\1/p')"
  [ -f /tmp/vpn-portal-login.last ] && read last t < /tmp/vpn-portal-login.last
  [ "$last" = "$ap" ] && [ $((now - ${t:-0})) -lt 300 ] && return 1
  echo "$ap $now" > /tmp/vpn-portal-login.last
  log "login page on the uplink, trying automatic login"
  /usr/bin/vpn-portal-login
}

now=$(date +%s)
dev="$(ifstatus "$UPLINK" 2>/dev/null | jsonfilter -e '@.l3_device')"

case "$1" in
  portal)
    if [ "$2" = close ]; then
      portal_close
    else
      min=${2:-$PORTALMIN}
      case "$min" in ''|*[!0-9]*) min=5 ;; esac
      echo $((now + min * 60)) > "$PORTAL"
      log "hotel login window open for $min min"
      all_down
      portal_open_rule "$dev"
    fi
    exit 0
    ;;
esac

# 0. While the hotel login window is open keep the VPN down, so the login
#    page goes out over the plain uplink. Close it once the time is up.
if [ -f "$PORTAL" ]; then
  read ends < "$PORTAL"
  if [ "$now" -lt "${ends:-0}" ]; then
    all_down
    portal_open_rule "$dev"
    exit 0
  fi
  portal_close
fi

[ "$ENABLED" = 1 ] || { set_dns; exit 0; }

# 1. The uplink must reach the internet on its own first. Until it does
#    (no Wi-Fi yet, or a captive portal still waiting for a login) keep
#    every tunnel down so the portal page can load. Some portals let ping
#    through, so also trust travelmate when it has seen a portal.
# Ping first; some hotels block ICMP, so fall back to an HTTP check that a
# portal can't fake (it must answer 204 with an empty body).
uplink_online() {
  ping -c 2 -W 3 -I "$dev" 1.1.1.1 >/dev/null 2>&1 && return 0
  [ "$(curl -s -o /dev/null -w '%{http_code}' --interface "$dev" -m 8 \
        http://connectivitycheck.gstatic.com/generate_204 2>/dev/null)" = 204 ]
}
if ! is_up "$UPLINK"; then
  [ -f "$STATE" ] && log "uplink is down, stopping VPN"
  all_down
  exit 0
fi
if ! uplink_online || trm_portal; then
  [ -f "$STATE" ] && log "uplink has no internet or shows a login page, stopping VPN"
  all_down
  # the login runs from the router; the LAN stays blocked meanwhile
  portal_autologin && uplink_online || exit 0
fi

if [ -z "$VPNS" ]; then
  [ -f "$STATE" ] && log "no enabled tunnels in region '$REGION', stopping VPN"
  all_down
  exit 0
fi

cur=""; since=0
[ -f "$STATE" ] && read cur since < "$STATE"

# Adopt a tunnel that was started by hand, at boot or by netifd, and record
# it so it gets the usual grace period and logging.
if [ -z "$cur" ]; then
  for v in $VPNS; do
    is_up "$v" && { cur=$v; since=$now; echo "$cur $now" > "$STATE"; log "adopting $cur"; break; }
  done
fi

# The region was changed, or the tunnel was disabled or deleted: drop it
# and start the first tunnel of the region.
if [ -n "$cur" ] && ! in_list "$cur" "$VPNS"; then
  log "$cur is not in region '$REGION' any more"
  is_up "$cur" && ifdown "$cur"
  cur=""
fi

healthy() {
  is_up "$1" || return 1
  hs=$(wg show "$1" latest-handshakes 2>/dev/null | awk '$2>m{m=$2} END{print m+0}')
  [ "$hs" -gt 0 ] && [ $((now - hs)) -lt "$MAXAGE" ] || return 1
  ping -c 2 -W 3 -I "$1" 1.1.1.1 >/dev/null 2>&1
}

# 2. Keep the current tunnel while it works, and make sure it is the only one up.
if [ -n "$cur" ]; then
  for v in $ALL; do [ "$v" != "$cur" ] && is_up "$v" && ifdown "$v"; done
  if [ "$1" = next ]; then
    log "switching from $cur on request"
  else
    healthy "$cur" && { set_dns "$cur"; exit 0; }
    [ $((now - since)) -lt "$GRACE" ] && exit 0
    log "$cur is not passing traffic, switching"
  fi
  ifdown "$cur"
else
  for v in $ALL; do is_up "$v" && ifdown "$v"; done
fi

# 3. Start the next tunnel in the list, wrapping round to the first.
set -- $VPNS
first=$1; next=$1
if [ -n "$cur" ]; then
  while [ $# -gt 0 ]; do
    [ "$1" = "$cur" ] && { next=${2:-$first}; break; }
    shift
  done
fi
log "starting $next (region '$REGION')"
set_dns
ifup "$next"
echo "$next $now" > "$STATE"
VPNREGIONS_EOF

cat > /usr/bin/vpn-portal-login <<'VPNREGIONS_EOF'
#!/bin/sh
# vpn-portal-login: get through a hotel or public Wi-Fi login page from the
# router itself, so devices on the LAN stay behind the kill switch.
#
#   vpn-portal-login            try to log in; exit 0 once the uplink is online
#   vpn-portal-login capture    only save the portal's pages for later
#
# It knows a few portal systems (Meraki, Cisco WLC, OPNsense, MikroTik trial)
# and otherwise fills in the page's form: ticks the terms box, keeps hidden
# fields, and enters surname, room and e-mail from /etc/config/vpnregions.
# A portal it can't get through is saved under /root/portal-captures, so a
# login for it can be written later.

export PATH=/usr/sbin:/usr/bin:/sbin:/bin
MODE="$1"
[ -n "$VPN_TEST" ] || . /lib/functions.sh

PROBE="${VPN_PROBE:-http://detectportal.firefox.com/success.txt}"   # answers "success"
CAPDIR="${VPN_CAPDIR:-/root/portal-captures}"
KEEP=10                       # captures kept
WORK="${VPN_WORK:-/tmp/vpn-portal-login}"
DNSAUTO="/tmp/resolv.conf.d/resolv.conf.auto"
UA="Mozilla/5.0 (X11; Linux x86_64; rv:144.0) Gecko/20100101 Firefox/144.0"

if [ -n "$VPN_TEST" ]; then
  UPLINK=wwan; SURNAME="$VPN_SURNAME"; ROOM="$VPN_ROOM"; EMAIL="$VPN_EMAIL"
  dev="$VPN_DEV"; ssid=test; bssid=test
else
  config_load vpnregions
  config_get UPLINK main uplink wwan
  config_get SURNAME main portal_surname ""
  config_get ROOM main portal_room ""
  config_get EMAIL main portal_email ""
  dev="$(ifstatus "$UPLINK" 2>/dev/null | jsonfilter -e '@.l3_device')"
  ssid="$(iwinfo "$dev" info 2>/dev/null | sed -n 's/.*ESSID: "\(.*\)".*/\1/p')"
  bssid="$(iwinfo "$dev" info 2>/dev/null | sed -n 's/.*Access Point: \([0-9A-Fa-f:]*\).*/\1/p')"
fi
[ -n "$dev" ] || { echo "uplink is not connected"; exit 1; }

log() { [ -n "$VPN_TEST" ] && echo "LOG $*" >&2 || logger -t vpn-portal-login "$*"; echo "# $*" >> "$WORK/trace"; }

rm -rf "$WORK"; mkdir -p "$WORK"
JAR="$WORK/cookies"; : > "$JAR"; : > "$WORK/trace"; : > "$WORK/urls"

# The uplink's own DNS server, asked directly: dnsmasq may be pointed at the
# VPN's DNS, and its rebind protection hides portals on private addresses.
updns="$(awk -v i="$UPLINK" '/^# Interface /{c=$3} /^nameserver/ && c==i {print $2; exit}' "$DNSAUTO" 2>/dev/null)"

resolve() {
  case "$1" in *[!0-9.]*) ;; *) echo "$1"; return ;; esac
  [ -n "$updns" ] || return
  nslookup "$1" "$updns" 2>/dev/null |
    awk '/^Name:/{n=1} n && /^Address/ {sub(/^Address[^:]*: */,""); if ($1 ~ /^[0-9.]+$/) {print $1; exit}}'
}

urlhost() { echo "$1" | sed -n 's#^[A-Za-z]*://\([^/:?]*\).*#\1#p'; }
urlport() {
  p="$(echo "$1" | sed -n 's#^[A-Za-z]*://[^/:?]*:\([0-9]*\).*#\1#p')"
  [ -n "$p" ] && echo "$p" || case "$1" in https:*) echo 443 ;; *) echo 80 ;; esac
}
origin() { echo "$1" | sed -n 's#^\([A-Za-z]*://[^/?]*\).*#\1#p'; }

# absolute URL for a link $2 found on page $1
absurl() {
  case "$2" in
    http://*|https://*) echo "$2" ;;
    //*) echo "${1%%:*}:$2" ;;
    /*) echo "$(origin "$1")$2" ;;
    "") echo "${1%%#*}" ;;
    \?*) echo "${1%%\?*}$2" ;;
    *) b="${1%%\?*}"; echo "${b%/*}/$2" ;;
  esac
}

urldecode() {
  echo "$1" | awk 'BEGIN { for (i = 0; i < 256; i++) h[sprintf("%02X", i)] = sprintf("%c", i) }
    { gsub(/\+/, " "); r = ""; while (match($0, /%[0-9A-Fa-f][0-9A-Fa-f]/)) {
        r = r substr($0, 1, RSTART - 1) h[toupper(substr($0, RSTART + 1, 2))]; $0 = substr($0, RSTART + 3) }
      print r $0 }'
}
urlencode() { printf '%s' "$1" | awk 'BEGIN{for(i=0;i<256;i++)o[sprintf("%c",i)]=i} {s=(NR>1?"%0A":""); for(i=1;i<=length($0);i++){c=substr($0,i,1); s=s (c~/[A-Za-z0-9._~-]/?c:sprintf("%%%02X",o[c]))} printf "%s",s}'; }
qparam() { echo "$1" | sed -n "s/.*[?&]$2=\([^&#]*\).*/\1/p"; }

# fetch URL [POSTDATA]: follow redirects by hand (each host resolved through
# the uplink's DNS), log everything for a capture, leave the final page in
# $WORK/page and its address in $URL.
fetch() {
  url="$1"; data="$2"; n=0
  while :; do
    n=$((n + 1)); host="$(urlhost "$url")"; port="$(urlport "$url")"; ip="$(resolve "$host")"
    set -- -sk -m 15 --interface "$dev" -A "$UA" -b "$JAR" -c "$JAR" -D "$WORK/hdr" -o "$WORK/page"
    [ -n "$ip" ] && [ "$ip" != "$host" ] && set -- "$@" --resolve "$host:$port:$ip"
    [ -n "$data" ] && set -- "$@" --data "$data" -H "Content-Type: application/x-www-form-urlencoded"
    code="$(curl "$@" -w '%{http_code}' "$url" 2>/dev/null)"
    { echo; echo "== $([ -n "$data" ] && echo POST || echo GET) $url -> $code"; [ -n "$data" ] && echo "-- data: $data"
      cat "$WORK/hdr" 2>/dev/null; head -c 60000 "$WORK/page" 2>/dev/null; echo; } >> "$WORK/trace"
    echo "$url" >> "$WORK/urls"
    URL="$url"; CODE="$code"
    loc="$(sed -n 's/^[Ll]ocation: *\(.*\)\r*$/\1/p' "$WORK/hdr" 2>/dev/null | tr -d '\r' | tail -n 1)"
    case "$code" in 30[1278]) ;; *) return 0 ;; esac
    [ -n "$loc" ] && [ "$n" -lt 10 ] || return 0
    url="$(absurl "$url" "$loc")"
    [ "$code" = 307 ] || [ "$code" = 308 ] || data=""
  done
}

online() {
  curl -sk -m 10 --interface "$dev" -o "$WORK/probe" "$PROBE" 2>/dev/null &&
    [ "$(tr -d ' \r\n' < "$WORK/probe")" = success ]
}

# meta refresh or a JavaScript redirect on the current page
softredirect() {
  tr '\n\r' '  ' < "$WORK/page" | awk '{
    l=tolower($0)
    if (match(l, /http-equiv=["'"'"']?refresh["'"'"']?[^>]*url=[^"'"'"'>]+/)) { s=substr($0,RSTART,RLENGTH); sub(/.*[Uu][Rr][Ll]=/,"",s); print s; exit }
    if (match($0, /(window\.|document\.|top\.)?location(\.href)? *= *["'"'"'][^"'"'"']+/)) { s=substr($0,RSTART,RLENGTH); sub(/^[^"'"'"']*["'"'"']/,"",s); print s; exit }
    if (match($0, /location\.replace\( *["'"'"'][^"'"'"']+/)) { s=substr($0,RSTART,RLENGTH); sub(/^[^"'"'"']*["'"'"']/,"",s); print s; exit }
  }' | sed 's/&amp;/\&/g'
}

# Fill in the most promising form on the page. Prints "METHOD<TAB>action"
# then the encoded body, or "NEED<TAB>field" when a required field can't be
# filled.
formfill() {
  tr '\n\r\t' '   ' < "$WORK/page" | awk -v sn="$SURNAME" -v rm="$ROOM" -v em="$EMAIL" '
  function attr(t, n,   l, s) {
    l = tolower(t)
    if (match(l, "[ \t]" n "[ \t]*=[ \t]*\"[^\"]*\"")) { s = substr(t, RSTART, RLENGTH); sub(/^[^"]*"/, "", s); sub(/"$/, "", s); return ent(s) }
    if (match(l, "[ \t]" n "[ \t]*=[ \t]*\047[^\047]*\047")) { s = substr(t, RSTART, RLENGTH); sub(/^[^\047]*\047/, "", s); sub(/\047$/, "", s); return ent(s) }
    if (match(l, "[ \t]" n "[ \t]*=[ \t]*[^ \t>\"\047]+")) { s = substr(t, RSTART, RLENGTH); sub(/^[^=]*=[ \t]*/, "", s); return ent(s) }
    return ""
  }
  function has(t, n) { return match(tolower(t), "[ \t]" n "([ \t=/>]|$)") }
  function ent(s) { gsub(/&amp;/, "\\&", s); gsub(/&quot;/, "\"", s); gsub(/&#0?39;/, "\047", s); gsub(/&lt;/, "<", s); gsub(/&gt;/, ">", s); return s }
  function enc(s,   i, c, r) { r = ""; for (i = 1; i <= length(s); i++) { c = substr(s, i, 1); r = r (c ~ /[A-Za-z0-9._~-]/ ? c : sprintf("%%%02X", ord[c])) } return r }
  function add(f, n, v) { if (n == "") return; body[f] = body[f] (body[f] == "" ? "" : "&") enc(n) "=" enc(v) }
  BEGIN { for (i = 0; i < 256; i++) ord[sprintf("%c", i)] = i; nf = 0; f = 0 }
  {
    nt = split($0, parts, "<")
    for (k = 2; k <= nt; k++) {
      t = " " parts[k]; sub(/>.*/, "", t); tag = tolower(t); sub(/^ /, "", tag); sub(/[ \t].*/, "", tag); if (tag !~ /^\//) sub(/\/.*/, "", tag)
      if (tag == "form") { nf++; f = nf; act[f] = attr(t, "action"); meth[f] = toupper(attr(t, "method")); if (meth[f] == "") meth[f] = "GET"; continue }
      if (tag == "/form") { f = 0; continue }
      if (tag == "option" && sel != "") { v = attr(t, "value"); if (!(sel in selv) || has(t, "selected")) selv[sel] = v; continue }
      if (tag == "/select") { if (sel in selv) add(sf, sel, selv[sel]); sel = ""; continue }
      if (f == 0 && tag != "a") continue
      if (tag == "a") { h = attr(t, "href"); if (h ~ /[?&]username=T-/ || tolower(h) ~ /\/grant\?|accept|continue|agree|connect/) link = (link == "" ? h : link); continue }
      if (tag == "select") { sel = attr(t, "name"); sf = f; continue }
      if (tag == "textarea") { add(f, attr(t, "name"), ""); continue }
      if (tag != "input" && tag != "button") continue
      ty = tolower(attr(t, "type")); if (ty == "") ty = (tag == "button" ? "submit" : "text")
      n = attr(t, "name"); v = attr(t, "value")
      key = tolower(n " " attr(t, "id") " " attr(t, "placeholder") " " attr(t, "aria-label"))
      req = has(t, "required")
      if (ty == "hidden") { add(f, n, v); continue }
      if (ty == "submit" || ty == "image") { if (!(f in sub_) && n != "") { sub_[f] = 1; add(f, n, v) } score[f] += 1; continue }
      if (ty == "checkbox") { cbx[f]++; if (req || key ~ /term|agree|accept|tos|aup|condition|policy|consent|rule|disclaim/) { add(f, n, (v == "" ? "on" : v)); score[f] += 2 } else lone[f] = n "\t" v; continue }
      if (ty == "radio") { if (!((f, n) in radio) || has(t, "checked")) radio[f, n] = v; continue }
      if (ty == "button" || ty == "reset" || ty == "file") continue
      if (key ~ /room|zimmer|chambre|habitaci|camera|kamer/) { fill = rm; score[f] += 3 }
      else if (key ~ /surname|last.?name|lastname|family|nachname|apellido|nom de famille|cognome|achternaam/) { fill = sn; score[f] += 3 }
      else if (key ~ /mail/) fill = em
      else if (ty == "password" || key ~ /pass|voucher|code|pin|otp|token/) { fill = v; if (v == "") { pw[f] = n } }
      else if (key ~ /(^| )(name|guest|gast)/) { fill = sn }
      else fill = v
      if (fill == "" && (req || ty == "password")) need[f] = need[f] (need[f] == "" ? "" : ",") n
      add(f, n, fill)
    }
  }
  END {
    best = 0; bs = -99
    for (i = 1; i <= nf; i++) {
      for (r in radio) { split(r, rr, SUBSEP); if (rr[1] == i) add(i, rr[2], radio[r]) }
      if (cbx[i] == 1 && lone[i] != "") { split(lone[i], lv, "\t"); add(i, lv[1], (lv[2] == "" ? "on" : lv[2])) }
      s = score[i] - (i in need ? 10 : 0) - (tolower(act[i]) ~ /search|lang/ ? 5 : 0)
      if (s > bs) { bs = s; best = i }
    }
    if (best && (best in need) && link != "") { print "LINK\t" link; exit }
    if (best && (best in need)) { print "NEED\t" need[best]; exit }
    if (best) { print meth[best] "\t" act[best]; print body[best]; exit }
    if (link != "") { print "LINK\t" link; exit }
  }'
}

# Known portal systems, recognised from the address bar
vendor() {
  urls="$(cat "$WORK/urls")"
  g="$(for u in $urls; do qparam "$u" base_grant_url; done | head -n 1)"
  if [ -n "$g" ]; then
    c="$(for u in $urls; do qparam "$u" user_continue_url; done | head -n 1)"
    log "Meraki portal, using its click-through grant"
    fetch "$(urldecode "$g")?continue_url=${c:-http%3A%2F%2Fexample.com}&duration=86400"; return 0
  fi
  s="$(for u in $urls; do qparam "$u" switch_url; done | head -n 1)"
  if [ -n "$s" ]; then
    r="$(for u in $urls; do qparam "$u" redirect; done | head -n 1)"
    log "Cisco WLC portal, sending its web-passthrough form"
    fetch "$(urldecode "$s")" "buttonClicked=4&err_flag=0&err_msg=&info_flag=0&info_msg=&redirect_url=${r:-http%3A%2F%2Fexample.com}"; return 0
  fi
  case "$URL" in
    http*://*:80[0-9][0-9]/index.html*)
      if grep -qi captiveportal "$WORK/page"; then
        p="$(urlport "$URL")"
        log "OPNsense portal, logging on to zone $((p - 8000))"
        fetch "$(origin "$URL")/api/captiveportal/access/logon/$((p - 8000))" "user=&password="; return 0
      fi ;;
  esac
  return 1
}

capture() {
  # one capture per access point until the router restarts
  grep -qx "${bssid:-x}" /tmp/vpn-portal-captured 2>/dev/null && [ "$MODE" != capture ] && return
  echo "${bssid:-x}" >> /tmp/vpn-portal-captured
  # JavaScript portals keep their logic in script files: save those too
  for js in $(tr '\n' ' ' < "$WORK/page" | grep -o '<script[^>]*src=["'"'"'][^"'"'"']*' | sed 's/.*src=["'"'"']//' | head -n 5); do
    fetch "$(absurl "$URL" "$js")"
  done
  mkdir -p "$CAPDIR"
  f="$CAPDIR/$(date +%Y%m%d-%H%M%S)-$(echo "${ssid:-unknown}" | tr -c 'A-Za-z0-9_-' _ | cut -c1-24).txt"
  { echo "Portal capture for later automation"
    echo "date: $(date)"; echo "ssid: $ssid"; echo "bssid: $bssid"; echo "uplink: $dev"
    echo "result: $1"
    echo "travelmate: $(jsonfilter -i /var/run/travelmate/travelmate.runtime.json -e '@.data.travelmate_status' 2>/dev/null)"
    echo; echo "== addresses visited"; cat "$WORK/urls"
    echo; echo "== cookies"; grep -v '^#' "$JAR" | sed 's/\t[^\t]*$/\t<value hidden>/'
    cat "$WORK/trace"
  } | head -c 400000 > "$f"
  ls -1t "$CAPDIR"/*.txt 2>/dev/null | tail -n +$((KEEP + 1)) | while read -r old; do rm -f "$old"; done
  log "saved portal capture $f"
}

# --- main -------------------------------------------------------------------

fetch "$PROBE"
if [ "$CODE" = 200 ] && [ "$(tr -d ' \r\n' < "$WORK/page")" = success ]; then
  [ "$MODE" = capture ] && { log "no login page right now"; exit 0; }
  exit 0
fi

if [ "$MODE" = capture ]; then capture "captured on request"; exit 0; fi

log "login page found at $URL"
round=0; why=""; tried=""
while [ "$round" -lt 5 ]; do
  round=$((round + 1))
  if [ -z "$tried" ] && vendor; then tried=1
  else
    out="$(formfill)"
    kind="$(echo "$out" | head -n 1 | cut -f1)"; target="$(echo "$out" | head -n 1 | cut -f2-)"
    case "$kind" in
      GET|POST)
        body="$(echo "$out" | sed -n 2p)"
        dest="$(absurl "$URL" "$target")"
        log "submitting form to $dest"
        if [ "$kind" = POST ]; then fetch "$dest" "$body"
        else case "$dest" in *\?*) fetch "$dest&$body" ;; *) fetch "$dest?$body" ;; esac; fi ;;
      LINK) dest="$(absurl "$URL" "$target")"; log "following $dest"; fetch "$dest" ;;
      NEED) why="the page needs $target, which isn't set (surname/room/e-mail, or a password or voucher)"; break ;;
      *)
        r="$(softredirect)"
        if [ -n "$r" ]; then fetch "$(absurl "$URL" "$r")"
        else why="no form on the page (probably a JavaScript-only portal)"; break; fi ;;
    esac
  fi
  if online; then log "logged in after $round step(s)"; exit 0; fi
done

capture "automatic login failed: ${why:-still offline after $round steps}"
log "automatic login failed: ${why:-still offline}"
exit 1
VPNREGIONS_EOF

cat > /www/luci-static/resources/view/vpnregions.js <<'VPNREGIONS_EOF'
'use strict';
'require view';
'require form';
'require uci';
'require fs';
'require ui';

/*
 * VPN Regions: import WireGuard configs, tag them with a region and choose
 * which region /usr/bin/vpn-failover.sh cycles through.
 */

const FAILOVER = '/usr/bin/vpn-failover.sh';
const TRM_RUNTIME = '/var/run/travelmate/travelmate.runtime.json';
const PORTAL_MINUTES = '5';
const PORTAL_LOGIN = '/usr/bin/vpn-portal-login';
const CAPDIR = '/root/portal-captures';

function wgInterfaces() {
	return uci.sections('network', 'interface').filter(s => s.proto == 'wireguard').map(s => s['.name']);
}

function regions() {
	const seen = {};
	uci.sections('vpnregions', 'tunnel').forEach(s => { if (s.region) seen[s.region] = true; });
	return Object.keys(seen).sort();
}

function peersOf(iface) {
	return uci.sections('network', 'wireguard_' + iface).filter(p => p.disabled != '1');
}

function ago(secs) {
	if (secs < 120) return _('%ds ago').format(secs);
	if (secs < 7200) return _('%d min ago').format(Math.floor(secs / 60));
	return _('%d h ago').format(Math.floor(secs / 3600));
}

/* Parse a wg-quick style .conf (as downloaded from Proton and most providers). */
function parseConf(text) {
	const conf = { iface: {}, peers: [] };
	let sec = null, peer = null;

	text.split(/\r?\n/).forEach(line => {
		let m = line.match(/^\s*#\s*(.*?)\s*$/);
		if (m) {
			/* Proton puts the server name as a comment right after [Peer] */
			if (sec == 'peer' && peer.comment == null && m[1] && m[1].indexOf('=') < 0)
				peer.comment = m[1];
			return;
		}

		line = line.trim();
		if (!line) return;

		if ((m = line.match(/^\[\s*(\w+)\s*\]$/))) {
			sec = m[1].toLowerCase();
			if (sec == 'peer') conf.peers.push(peer = {});
			return;
		}

		if ((m = line.match(/^(\w+)\s*=\s*(.*)$/)) && sec)
			(sec == 'peer' ? peer : conf.iface)[m[1].toLowerCase()] = m[2].trim();
	});

	if (!conf.iface.privatekey || !conf.iface.address)
		throw new Error(_('no [Interface] PrivateKey or Address'));
	if (!conf.peers.length || !conf.peers[0].publickey || !conf.peers[0].endpoint)
		throw new Error(_('no [Peer] with PublicKey and Endpoint'));

	return conf;
}

function splitList(v) {
	return (v || '').split(/[\s,]+/).filter(x => x);
}

/* Interface names become Linux device names: 15 characters at most. */
function uniqueName(hint) {
	const taken = {};
	uci.sections('network').forEach(s => taken[s['.name'].toLowerCase()] = true);

	let base = 'wg_' + (hint || 'vpn').replace(/[^A-Za-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
	base = base.substring(0, 15);

	let name = base;
	for (let i = 2; taken[name.toLowerCase()]; i++)
		name = base.substring(0, 15 - String(i).length - 1) + '_' + i;

	return name;
}

function isDuplicate(peer) {
	return uci.sections('network').some(s =>
		s['.type'].indexOf('wireguard_') == 0 && s.public_key == peer.publickey &&
		(s.endpoint_host + ':' + s.endpoint_port) == peer.endpoint);
}

/* Create interface + peer + firewall zone membership + failover entry. */
function addTunnel(conf, hint, region, zone) {
	const name = uniqueName(conf.peers[0].comment || hint);
	const i = conf.iface;

	uci.add('network', 'interface', name);
	uci.set('network', name, 'proto', 'wireguard');
	uci.set('network', name, 'private_key', i.privatekey);
	uci.set('network', name, 'addresses', splitList(i.address));
	if (i.dns) uci.set('network', name, 'dns', splitList(i.dns));
	if (i.mtu) uci.set('network', name, 'mtu', i.mtu);
	uci.set('network', name, 'auto', '0');     /* vpn-failover starts it */
	uci.set('network', name, 'metric', '10');  /* below the uplink's 20 */

	const p = conf.peers[0];
	const m = p.endpoint.match(/^\[?(.+?)\]?:(\d+)$/);
	const sid = uci.add('network', 'wireguard_' + name);
	uci.set('network', sid, 'description', p.comment || hint);
	uci.set('network', sid, 'public_key', p.publickey);
	if (p.presharedkey) uci.set('network', sid, 'preshared_key', p.presharedkey);
	uci.set('network', sid, 'endpoint_host', m ? m[1] : p.endpoint);
	if (m) uci.set('network', sid, 'endpoint_port', m[2]);
	uci.set('network', sid, 'allowed_ips', splitList(p.allowedips || '0.0.0.0/0, ::/0'));
	uci.set('network', sid, 'route_allowed_ips', '1');
	uci.set('network', sid, 'persistent_keepalive', p.persistentkeepalive || '25');

	const z = uci.sections('firewall', 'zone').find(s => s.name == zone);
	if (z) {
		const nets = L.toArray(z.network);
		nets.push(name);
		uci.set('firewall', z['.name'], 'network', nets);
	}

	const t = uci.add('vpnregions', 'tunnel');
	uci.set('vpnregions', t, 'iface', name);
	uci.set('vpnregions', t, 'region', region);
	uci.set('vpnregions', t, 'enabled', '1');

	return name;
}

function deleteInterface(iface) {
	uci.sections('network', 'wireguard_' + iface).forEach(p => uci.remove('network', p['.name']));
	uci.remove('network', iface);

	uci.sections('firewall', 'zone').forEach(z => {
		const nets = L.toArray(z.network);
		if (nets.indexOf(iface) >= 0)
			uci.set('firewall', z['.name'], 'network', nets.filter(n => n != iface));
	});
}

function readFile(file) {
	return new Promise((resolve, reject) => {
		const r = new FileReader();
		r.onload = () => resolve(r.result);
		r.onerror = () => reject(r.error);
		r.readAsText(file);
	});
}

return view.extend({
	load() {
		return uci.load('vpnregions').then(() => Promise.all([
			uci.load('network'),
			uci.load('firewall'),
			L.resolveDefault(fs.read('/tmp/vpn-failover'), ''),
			L.resolveDefault(fs.exec('/usr/bin/wg', [ 'show', 'all', 'latest-handshakes' ]), {}),
			L.resolveDefault(fs.read('/tmp/vpn-portal'), ''),
			L.resolveDefault(fs.read(TRM_RUNTIME).then(JSON.parse), {}),
			L.resolveDefault(uci.load('travelmate'), null),
			L.resolveDefault(fs.list(CAPDIR), [])
		]));
	},

	showImport() {
		const zones = uci.sections('firewall', 'zone').map(z => z.name).filter(n => n && n != 'lan' && n != 'wan');
		const regionInput = E('input', { 'class': 'cbi-input-text', 'list': 'vpnregions-list', 'placeholder': _('e.g. Switzerland') });
		const zoneSelect = E('select', { 'class': 'cbi-input-select' },
			zones.map(n => E('option', { 'value': n, 'selected': n == 'VPN' || null }, n)));
		const fileInput = E('input', { 'type': 'file', 'accept': '.conf,text/plain', 'multiple': true });
		const pasteArea = E('textarea', { 'class': 'cbi-input-textarea', 'rows': 8, 'style': 'width:100%;font-family:monospace',
			'placeholder': '[Interface]\nPrivateKey = ...\nAddress = 10.2.0.2/32\n\n[Peer]\nPublicKey = ...\nEndpoint = 1.2.3.4:51820' });

		const row = (label, el, hint) => E('div', { 'class': 'cbi-value' }, [
			E('label', { 'class': 'cbi-value-title' }, label),
			E('div', { 'class': 'cbi-value-field' }, [ el, hint ? E('div', { 'class': 'cbi-value-description' }, hint) : '' ])
		]);

		ui.showModal(_('Add WireGuard configs'), [
			E('datalist', { 'id': 'vpnregions-list' }, regions().map(r => E('option', { 'value': r }))),
			row(_('Region'), regionInput, _('All imported configs get this region. Use the same name to group servers of one country.')),
			row(_('Firewall zone'), zoneSelect, _('Must be a VPN zone, so the kill switch lets LAN traffic through this tunnel.')),
			row(_('Config files'), fileInput, _('Pick one or more .conf files, as downloaded from your VPN provider.')),
			row(_('Or paste a config'), pasteArea),
			E('div', { 'class': 'right' }, [
				E('button', { 'class': 'cbi-button', 'click': ui.hideModal }, _('Cancel')), ' ',
				E('button', { 'class': 'cbi-button cbi-button-positive', 'click': ui.createHandlerFn(this, () => {
					const region = regionInput.value.trim();
					if (!/^[A-Za-z0-9_-]{1,32}$/.test(region) || region == 'all') {
						ui.addNotification(null, E('p', _('Enter a region name using letters, digits, - or _ only.')), 'warning');
						return;
					}

					const sources = Array.from(fileInput.files).map(f =>
						readFile(f).then(text => ({ hint: f.name.replace(/\.conf$/i, ''), text })));
					if (pasteArea.value.trim())
						sources.push(Promise.resolve({ hint: region, text: pasteArea.value }));
					if (!sources.length) {
						ui.addNotification(null, E('p', _('Choose a file or paste a config first.')), 'warning');
						return;
					}

					return Promise.all(sources).then(items => {
						const added = [], problems = [];

						items.forEach(it => {
							try {
								const conf = parseConf(it.text);
								if (isDuplicate(conf.peers[0]))
									problems.push(_('%s: already added').format(it.hint));
								else
									added.push(addTunnel(conf, it.hint, region, zoneSelect.value));
							}
							catch (e) {
								problems.push('%s: %s'.format(it.hint, e.message));
							}
						});

						ui.hideModal();
						if (problems.length)
							ui.addNotification(_('Some configs were skipped'), E('ul', problems.map(p => E('li', p))), 'warning');
						if (!added.length)
							return;

						ui.addNotification(null, E('p', _('Added %s. Applying…').format(added.join(', '))), 'info');
						return uci.save().then(() => ui.changes.apply(true));
					});
				}) }, _('Import'))
			])
		]);
	},

	render(data) {
		const stateLine = String(data[2] || '').trim().split(/\s+/);
		const handshakes = {};
		String(data[3].stdout || '').split('\n').forEach(l => {
			const f = l.trim().split(/\s+/);
			if (f.length == 3) handshakes[f[0]] = Math.max(handshakes[f[0]] || 0, +f[2]);
		});
		const active = stateLine[0] || null;
		const now = Math.floor(Date.now() / 1000);
		const portalEnds = +String(data[4] || '').trim() || 0;
		const portalOpen = portalEnds > now;
		const trm = (data[5] && data[5].data) || {};
		const trmEnabled = uci.get('travelmate', 'global', 'trm_enabled') == '1';
		const trmStatus = trm.travelmate_status || '';
		const trmPortal = trmEnabled && /net cp/.test(trmStatus);
		const trmVpn = uci.get('travelmate', 'global', 'trm_vpn') == '1';
		const captures = (data[7] || []).filter(f => f.type == 'file' && /\.txt$/.test(f.name))
			.sort((a, b) => b.mtime - a.mtime);

		const m = new form.Map('vpnregions', _('VPN Regions'),
			_('Choose which WireGuard tunnels the failover script may use. It keeps one tunnel up and moves to the next one of the chosen region when it stops working. The kill switch stays on: if no tunnel works, nothing goes out.'));

		let s = m.section(form.NamedSection, 'main', 'settings', _('Failover'));

		let o = s.option(form.DummyValue, '_status', _('Status'));
		o.rawhtml = true;
		o.cfgvalue = () => {
			if (!active)
				return E('em', portalOpen ? _('VPN off while the hotel login window is open.')
					: _('No tunnel up (no uplink internet yet, a login page waiting, or no tunnel in this region).')).outerHTML;
			const hs = handshakes[active];
			return E('span', [
				E('strong', active), ' ',
				_('since %s').format(new Date(+stateLine[1] * 1000).toLocaleTimeString()), ', ',
				hs ? _('last handshake %s').format(ago(Math.max(0, now - hs))) : _('no handshake yet')
			]).outerHTML;
		};

		o = s.option(form.DummyValue, '_uplink', _('Wi-Fi uplink'));
		o.rawhtml = true;
		o.cfgvalue = () => {
			const parts = [];
			if (trmEnabled)
				parts.push(E('span', [ _('Travelmate: %s').format(trmStatus || _('no status yet')),
					trm.station_id ? ' (%s)'.format(trm.station_id.replace(/\/-$/, '')) : '' ]));
			else
				parts.push(E('em', _('Travelmate is off.')));
			parts.push(' ', E('a', { 'href': L.url('admin/services/travelmate') }, _('Join a Wi-Fi network…')));
			if (trmPortal)
				parts.push(E('div', { 'class': 'alert-message warning', 'style': 'margin:.5em 0 0' },
					_('This Wi-Fi has a login page. The router tries to sign in by itself; if that fails, use “Manual login” below.')));
			if (trmVpn)
				parts.push(E('div', { 'class': 'alert-message warning', 'style': 'margin:.5em 0 0' },
					_('Travelmate’s own VPN option is on. It takes down the tunnels this page starts. Use “Let VPN Regions handle the VPN” below.')));
			return E('div', parts).outerHTML;
		};

		if (trmVpn) {
			o = s.option(form.Button, '_trmvpn', ' ');
			o.inputtitle = _('Let VPN Regions handle the VPN');
			o.inputstyle = 'negative';
			o.onclick = () => {
				uci.set('travelmate', 'global', 'trm_vpn', '0');
				uci.sections('travelmate', 'uplink').forEach(u => {
					[ 'vpn', 'vpnservice', 'vpniface' ].forEach(k => uci.unset('travelmate', u['.name'], k));
				});
				return uci.save().then(() => ui.changes.apply(true));
			};
		}

		o = s.option(form.Flag, 'enabled', _('Enable failover'),
			_('When off, the script leaves the tunnels alone and you start them yourself.'));
		o.default = '1';
		o.rmempty = false;

		o = s.option(form.ListValue, 'region', _('Use region'),
			_('Only enabled tunnels of this region are used, in the order of the table below. Takes effect within a minute of Save & Apply.'));
		o.value('all', _('All regions'));
		regions().forEach(r => o.value(r));
		o.default = 'all';

		o = s.option(form.Button, '_check', _('Actions'),
			_('These act on the saved settings, so Save & Apply first.'));
		o.inputtitle = _('Check now');
		o.inputstyle = 'apply';
		o.onclick = () => fs.exec(FAILOVER).then(() => location.reload());

		o = s.option(form.Button, '_next', ' ');
		o.inputtitle = _('Switch to next tunnel');
		o.inputstyle = 'action';
		o.onclick = () => fs.exec(FAILOVER, [ 'next' ]).then(() => location.reload());

		o = s.option(form.Button, '_import', _('Add servers'),
			_('Import WireGuard .conf files from your VPN provider and give them a region.'));
		o.inputtitle = _('Add WireGuard configs');
		o.inputstyle = 'add';
		o.onclick = ui.createHandlerFn(this, 'showImport');

		o = s.option(form.Value, 'uplink', _('Uplink interface'),
			_('The Wi-Fi uplink. The VPN stays down until this reaches the internet.'));
		o.default = 'wwan';

		s = m.section(form.NamedSection, 'main', 'settings', _('Hotel Wi-Fi login'),
			_('When the Wi-Fi shows a login page, the router tries to sign in by itself while your devices stay blocked. It ticks the terms box and fills in the details below. If it can’t, it saves the page under “Saved login pages” so a login for it can be added later, and you use the manual login.'));

		o = s.option(form.Flag, 'portal_auto', _('Automatic login'));
		o.default = '1';
		o.rmempty = false;

		o = s.option(form.Value, 'portal_surname', _('Surname'), _('As on the booking. Many hotels ask for surname and room number.'));
		o.depends('portal_auto', '1');
		o = s.option(form.Value, 'portal_room', _('Room number'), _('Change this for each stay.'));
		o.depends('portal_auto', '1');
		o = s.option(form.Value, 'portal_email', _('E-mail'), _('Only used when a login page insists on one.'));
		o.datatype = 'string';
		o.depends('portal_auto', '1');

		o = s.option(form.Button, '_trylogin', _('Try now'), _('Uses the saved settings, so Save & Apply first.'));
		o.inputtitle = _('Try automatic login');
		o.inputstyle = trmPortal ? 'apply' : 'action';
		o.onclick = () => fs.exec(PORTAL_LOGIN).then(r => {
			ui.addNotification(null, E('p', r.code == 0 ? _('Online. The VPN starts within a minute.')
				: _('Automatic login didn’t get through; the page was saved below. Use the manual login instead.')), r.code == 0 ? 'info' : 'warning');
			return new Promise(res => setTimeout(res, 2500)).then(() => location.reload());
		});

		o = s.option(form.Button, '_portal', _('Manual login'), portalOpen
			? _('Open until %s: devices on your Wi-Fi can reach the login page, without the VPN. It closes by itself, then the VPN comes back.').format(new Date(portalEnds * 1000).toLocaleTimeString())
			: _('Opens the plain hotel connection for %s minutes so a phone or laptop can sign in to the hotel’s login page. The VPN is off during that time, and the kill switch comes back automatically.').format(PORTAL_MINUTES));
		o.inputtitle = portalOpen ? _('Close now') : _('Open for %s minutes').format(PORTAL_MINUTES);
		o.inputstyle = portalOpen ? 'reset' : (trmPortal ? 'apply' : 'action');
		o.onclick = () => fs.exec(FAILOVER, portalOpen ? [ 'portal', 'close' ] : [ 'portal', PORTAL_MINUTES ])
			.then(() => location.reload());

		o = s.option(form.DummyValue, '_captures', _('Saved login pages'));
		o.rawhtml = false;
		o.cfgvalue = () => '';
		o.renderWidget = () => {
			if (!captures.length)
				return E('em', _('None yet.'));
			return E('div', [
				E('ul', { 'style': 'margin:0 0 .5em 1.2em' }, captures.map(f => E('li', [
					E('a', { 'href': '#', 'click': ev => {
						ev.preventDefault();
						return fs.read(CAPDIR + '/' + f.name).then(txt => {
							const a = E('a', { 'href': URL.createObjectURL(new Blob([ txt ], { type: 'text/plain' })), 'download': f.name });
							document.body.appendChild(a); a.click(); a.remove();
						});
					} }, f.name), ' (%1024mB)'.format(f.size)
				]))),
				E('div', { 'class': 'cbi-value-description' }, _('Download one and send it over, and a login for that hotel can be added.')),
				E('button', { 'class': 'cbi-button cbi-button-remove', 'click': ui.createHandlerFn(this, () =>
					Promise.all(captures.map(f => fs.remove(CAPDIR + '/' + f.name))).then(() => location.reload())) }, _('Delete all'))
			]);
		};

		o = s.option(form.Button, '_capture', ' ', _('Save the current login page now, e.g. before you sign in by hand.'));
		o.inputtitle = _('Save this login page');
		o.inputstyle = 'action';
		o.onclick = () => fs.exec(PORTAL_LOGIN, [ 'capture' ]).then(() => location.reload());

		s = m.section(form.GridSection, 'tunnel', _('Tunnels'),
			_('Drag rows to change the order. “Add existing interface” adds a WireGuard interface you set up yourself under Network → Interfaces.'));
		s.anonymous = true;
		s.addremove = true;
		s.sortable = true;
		s.addbtntitle = _('Add existing interface');
		s.modaltitle = _('Tunnel');

		s.handleRemove = function(section_id, ev) {
			const iface = uci.get('vpnregions', section_id, 'iface');
			const done = (alsoIface) => {
				if (alsoIface && iface) deleteInterface(iface);
				ui.hideModal();
				return form.GridSection.prototype.handleRemove.call(this, section_id, ev);
			};

			return new Promise(resolve => {
				ui.showModal(_('Remove %s').format(iface || _('tunnel')), [
					E('p', _('Delete the WireGuard interface and its keys as well, or only take it out of the failover list?')),
					E('div', { 'class': 'right' }, [
						E('button', { 'class': 'cbi-button', 'click': () => { ui.hideModal(); resolve(); } }, _('Cancel')), ' ',
						E('button', { 'class': 'cbi-button', 'click': () => resolve(done(false)) }, _('Only remove from list')), ' ',
						E('button', { 'class': 'cbi-button cbi-button-negative', 'click': () => resolve(done(true)) }, _('Delete interface too'))
					])
				]);
			});
		};

		o = s.option(form.ListValue, 'iface', _('Interface'));
		wgInterfaces().forEach(n => o.value(n));
		o.rmempty = false;
		o.textvalue = function(section_id) {
			const v = this.cfgvalue(section_id);
			return v == active ? E('strong', [ v, ' ●' ]) : v;
		};

		o = s.option(form.DummyValue, '_server', _('Server'));
		o.modalonly = false;
		o.textvalue = function(section_id) {
			const p = peersOf(uci.get('vpnregions', section_id, 'iface'))[0];
			if (!p) return E('em', _('no enabled peer'));
			return '%s (%s:%s)'.format(p.description || '-', p.endpoint_host || '?', p.endpoint_port || '51820');
		};

		o = s.option(form.Value, 'region', _('Region'));
		regions().forEach(r => o.value(r));
		o.validate = (section_id, v) => (/^[A-Za-z0-9_-]{1,32}$/.test(v) && v != 'all') || _('Letters, digits, - and _ only');
		o.rmempty = false;
		o.editable = true;

		o = s.option(form.DummyValue, '_handshake', _('Last handshake'));
		o.modalonly = false;
		o.textvalue = function(section_id) {
			const hs = handshakes[uci.get('vpnregions', section_id, 'iface')];
			return hs ? ago(Math.max(0, now - hs)) : '-';
		};

		o = s.option(form.Flag, 'enabled', _('Enabled'));
		o.default = '1';
		o.rmempty = false;
		o.editable = true;

		return m.render();
	}
});
VPNREGIONS_EOF

cat > /usr/share/luci/menu.d/luci-app-vpnregions.json <<'VPNREGIONS_EOF'
{
	"admin/services/vpnregions": {
		"title": "VPN Regions",
		"order": 60,
		"action": {
			"type": "view",
			"path": "vpnregions"
		},
		"depends": {
			"acl": [ "luci-app-vpnregions" ],
			"uci": { "vpnregions": true }
		}
	}
}
VPNREGIONS_EOF

cat > /usr/share/rpcd/acl.d/luci-app-vpnregions.json <<'VPNREGIONS_EOF'
{
	"luci-app-vpnregions": {
		"description": "Grant access to VPN Regions",
		"read": {
			"file": {
				"/tmp/vpn-failover": [
					"read"
				],
				"/tmp/vpn-portal": [
					"read"
				],
				"/var/run/travelmate/travelmate.runtime.json": [
					"read"
				],
				"/usr/bin/wg show all latest-handshakes": [
					"exec"
				],
				"/root/portal-captures": [
					"list"
				],
				"/root/portal-captures/*": [
					"read"
				]
			},
			"uci": [
				"vpnregions",
				"network",
				"firewall",
				"travelmate"
			]
		},
		"write": {
			"file": {
				"/usr/bin/vpn-failover.sh": [
					"exec"
				],
				"/usr/bin/vpn-failover.sh next": [
					"exec"
				],
				"/usr/bin/vpn-failover.sh portal 5": [
					"exec"
				],
				"/usr/bin/vpn-failover.sh portal close": [
					"exec"
				],
				"/usr/bin/vpn-portal-login": [
					"exec"
				],
				"/usr/bin/vpn-portal-login capture": [
					"exec"
				],
				"/root/portal-captures/*": [
					"write"
				]
			},
			"uci": [
				"vpnregions",
				"network",
				"firewall",
				"travelmate"
			]
		}
	}
}
VPNREGIONS_EOF

chmod +x /usr/bin/vpn-failover.sh /usr/bin/vpn-portal-login
mkdir -p /root/portal-captures
uci -q get vpnregions.main.portal_auto >/dev/null || { uci set vpnregions.main.portal_auto='1'; uci commit vpnregions; }

# keep the add-on and saved login pages across firmware upgrades
for f in /usr/bin/vpn-failover.sh /usr/bin/vpn-portal-login /www/luci-static/resources/view/vpnregions.js \
         /usr/share/luci/menu.d/luci-app-vpnregions.json /usr/share/rpcd/acl.d/luci-app-vpnregions.json /root/portal-captures/; do
  grep -qxF "$f" /etc/sysupgrade.conf 2>/dev/null || echo "$f" >> /etc/sysupgrade.conf
done
grep -q vpn-failover.sh /etc/crontabs/root 2>/dev/null || {
  echo '* * * * * /usr/bin/vpn-failover.sh' >> /etc/crontabs/root
  /etc/init.d/cron enable
  /etc/init.d/cron restart
}
rm -rf /tmp/luci-indexcache* /tmp/luci-modulecache
/etc/init.d/rpcd reload

# travelmate looks after Wi-Fi only; its own VPN switching fights this script
if [ "$(uci -q get travelmate.global.trm_vpn)" = 1 ]; then
  uci set travelmate.global.trm_vpn='0'
  uci commit travelmate
  /etc/init.d/travelmate restart
  echo "Turned off travelmate's own VPN option (VPN Regions handles the VPN)."
fi

# DNS: dnsmasq takes its upstream servers from a file that vpn-failover.sh
# keeps pointed at the active tunnel's DNS, so lookups don't leak to the hotel
grep -v '^#' /tmp/resolv.conf.d/resolv.conf.auto > /tmp/resolv.conf.vpnregions 2>/dev/null
if [ "$(uci -q get dhcp.@dnsmasq[0].resolvfile)" != /tmp/resolv.conf.vpnregions ]; then
  uci set dhcp.@dnsmasq[0].resolvfile='/tmp/resolv.conf.vpnregions'
  uci commit dhcp
  /etc/init.d/dnsmasq restart
fi
sh /usr/bin/vpn-failover.sh

echo "Installed. Tunnels found:"
uci show vpnregions | grep -E "\.(iface|region)="
echo "Open LuCI → Services → VPN Regions (log out and back in if the menu entry is missing)."
if [ -n "$(has_fwd lan wan)" ]; then
  echo "Note: LAN -> WAN forwarding is still on, so traffic falls back to the plain uplink when no tunnel is up. Run again with --killswitch to block it."
fi
